llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Delpazolid (LCB01-0371), which shares the 5-hydroxymethyl oxazolidinone and 3-fluorophenyl core with the query, showed 99.75% absolute oral bioavailability in humans, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Linezolid, the prototypical oxazolidinone, is approximately 100% orally bioavailable in humans, supporting high F for the same scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Contezolid, another close oxazolidinone analogue, had F = 0.64 in healthy subjects, which is well above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a linezolid analogue with a thiomorpholine replacement, had low absolute oral bioavailability of 10.1%, providing a contradictory example within the oxazolidinone class.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cadazolid, a large oxazolidinone-quinolone hybrid, had very low oral bioavailability, but its much larger and more polar structure limits transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone with the same 5-hydroxymethyl/3-fluorophenyl pharmacophore as delpazolid, linezolid, and contezolid, all of which show high oral bioavailability (64-100%). The low-F analogues YH4808 and cadazolid are less transferable because of specific thiomorpholine or large quinolone modifications. Overall, the weight of direct experimental evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability value for the exact query free base; the marketed tedizolid form is a phosphate prodrug.",
    "Potential solubility-limited absorption of the poorly water-soluble free base is not directly captured by the high-F analogues.",
    "YH4808 demonstrates that minor scaffold changes can cause low F, so some uncertainty remains."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

